using System.Windows;
using System.Windows.Input;
using Microsoft.Win32;
using TaskCapture.Core;
namespace TaskCapture.Windows;
public partial class SetupWindow:Window {
 public AppSettings? Result{get;private set;}public List<TaskStage> ProposedStages{get;private set;}=[];private List<TaskStage> original;private bool existing=true;public bool AllowCreate{get;private set;}
 public SetupWindow(AppSettings? config=null,List<TaskStage>? stages=null){InitializeComponent();original=stages?.ToList()??TaskDocument.DefaultStages();HotkeyBox.Text=config?.Hotkey??"Ctrl+Shift+T";PathBox.Text=config?.MarkdownPath??"";Autostart.IsChecked=config?.StartOnLogin??false;existing=config is not null;LoadStages();SourceInitialized+=(_,_)=>Motion.Backdrop(this);Loaded+=(_,_)=>Motion.Appear((FrameworkElement)Content);}
 private void LoadStages(){StagesBox.Text=string.Join(Environment.NewLine,original.Select(s=>s.Name));LastDone.IsChecked=original.LastOrDefault()?.IsDone??false;StagesBox.IsReadOnly=existing;LastDone.IsEnabled=!existing;StageHint.Text=existing?"Этапы открытого файла изменяются через кнопку «Этапы задач» в главном окне. Их идентификаторы сохраняются.":"Бэклог — обязательный первый этап. Остальные этапы можно задать здесь.";}
 private void Pick_Click(object sender,RoutedEventArgs e){var picker=new SaveFileDialog{Filter="Markdown (*.md)|*.md",DefaultExt=".md",FileName="TaskCapture.md",OverwritePrompt=false,Title="Выберите MD-файл задач"};if(picker.ShowDialog(this)!=true)return;try{existing=File.Exists(picker.FileName);AllowCreate=!existing;if(existing)original=MarkdownCodec.Decode(File.ReadAllText(picker.FileName)).Stages;else original=TaskDocument.DefaultStages();PathBox.Text=picker.FileName;LoadStages();ErrorLabel.Text="";}catch(Exception ex){ErrorLabel.Text=ex.Message;}}
 private void Hotkey_KeyDown(object sender,KeyEventArgs e){e.Handled=true;Key key=e.Key==Key.System?e.SystemKey:e.Key;int vk=KeyInterop.VirtualKeyFromKey(key);if(vk is 16 or 17 or 18 or 91 or 92)return;var mods=Keyboard.Modifiers;List<string> pieces=[];if(mods.HasFlag(ModifierKeys.Control))pieces.Add("Ctrl");if(mods.HasFlag(ModifierKeys.Alt))pieces.Add("Alt");if(mods.HasFlag(ModifierKeys.Shift))pieces.Add("Shift");if(mods.HasFlag(ModifierKeys.Windows))pieces.Add("Win");pieces.Add(vk is >=48 and <=90?((char)vk).ToString():key.ToString());try{HotkeyBox.Text=TaskCapture.Core.Hotkey.Parse(string.Join('+',pieces)).Display;ErrorLabel.Text="";}catch(Exception ex){ErrorLabel.Text=ex.Message;}}
 private void Save_Click(object sender,RoutedEventArgs e){try{var hotkey=TaskCapture.Core.Hotkey.Parse(HotkeyBox.Text);if(string.IsNullOrWhiteSpace(PathBox.Text))throw new ArgumentException("Выберите MD-файл.");if(existing){ProposedStages=original.ToList();Result=new(System.IO.Path.GetFullPath(PathBox.Text),hotkey.Display,Autostart.IsChecked==true);DialogResult=true;return;}var names=StagesBox.Text.Split(['\r','\n'],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);if(names.Length==0||names[0]!="Бэклог")throw new ArgumentException("Первый этап должен называться Бэклог.");ProposedStages=names.Select((name,i)=>new TaskStage(i==0?"backlog":i<original.Count?original[i].Id:Guid.NewGuid().ToString("N"),name,i==0?false:i==names.Length-1?LastDone.IsChecked==true:i<original.Count&&original[i].IsDone)).ToList();MarkdownCodec.Validate(new(ProposedStages,[]));Result=new(System.IO.Path.GetFullPath(PathBox.Text),hotkey.Display,Autostart.IsChecked==true);DialogResult=true;}catch(Exception ex){ErrorLabel.Text=ex.Message;}}
}
